style.css:
@-moz-document domain("roblox.com") {
html, body {
    height: 100% !important;
    width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
    overflow-x: hidden !important;
  }

  body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    height: 100vh;
    width: 100vw;
    background-image: url("https://i.redd.it/larlog0qr9sb1.gif");
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center center;
    background-attachment: fixed;
    z-index: -9999;
    pointer-events: none;
  }

  /* Optional: transparent content layer */
  .container-main, .content, .section, .rbx-body {
    background-color: rgba(255, 255, 255, 0.85) !important;
  }
}
